mapper.select:
select place_id, name_ft, name_ch, name_py, x_coor, y_coor, type_ch, pres_loc, beg_yr, end_yr, source
from tj_place_dict
where name_ch = #{name}
   or name_ft = #{name}
   or (length(name_ch) between length(#{name}) + 1 and length(#{name}) + 2 and name_ch like concat(#{name}, '%'))
   or (length(name_ft) between length(#{name}) + 1 and length(#{name}) + 2 and name_ft like concat(#{name}, '%'))
